use bevy::{prelude::*, ui_widgets::{Activate, Button}};
use magistr_tic_tac_toe::{Board, Mark, Outcome};

#[derive(Resource, Default)]
struct Game(Board);
#[derive(Component)]
struct CellLabel(usize);
#[derive(Component)]
struct StatusLabel;
#[derive(Component)]
struct Cell(usize);

const INK: Color = Color::srgb(0.12, 0.15, 0.19);
const PAPER: Color = Color::srgb(0.96, 0.95, 0.91);
const CELL: Color = Color::srgb(1.0, 0.99, 0.96);
const X_COLOR: Color = Color::srgb(0.12, 0.34, 0.52);
const O_COLOR: Color = Color::srgb(0.65, 0.24, 0.12);

fn main() {
    App::new()
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window {
                title: "Tic-tac-toe".into(),
                resolution: (640, 620).into(),
                canvas: Some("#game".into()),
                fit_canvas_to_parent: true,
                prevent_default_event_handling: false,
                ..default()
            }),
            ..default()
        }))
        .insert_resource(ClearColor(PAPER))
        .init_resource::<Game>()
        .add_systems(Startup, setup)
        .add_systems(Update, (keyboard, draw).chain())
        .run();
}

fn label(text: impl Into<String>, size: f32) -> impl Bundle {
    (Text::new(text), TextFont { font_size: FontSize::Px(size), ..default() }, TextColor(INK))
}

fn setup(mut commands: Commands) {
    commands.spawn(Camera2d);
    commands.spawn(Node {
        width: percent(100), height: percent(100),
        flex_direction: FlexDirection::Column,
        align_items: AlignItems::Center, justify_content: JustifyContent::Center,
        row_gap: px(18), padding: UiRect::all(px(12)),
        ..default()
    }).with_children(|root| {
        root.spawn(label("Tic-tac-toe", 32.0));
        root.spawn((label("X to move", 18.0), StatusLabel));
        root.spawn(Node {
            display: Display::Grid, width: percent(100), max_width: px(330),
            aspect_ratio: Some(1.0), column_gap: px(6), row_gap: px(6),
            grid_template_columns: RepeatedGridTrack::flex(3, 1.0),
            grid_template_rows: RepeatedGridTrack::flex(3, 1.0), ..default()
        }).with_children(|grid| {
            for cell in 0..9 {
                grid.spawn((
                    Button, Cell(cell),
                    Node {
                        width: percent(100), height: percent(100),
                        align_items: AlignItems::Center, justify_content: JustifyContent::Center,
                        border: UiRect::all(px(1)), ..default()
                    },
                    BackgroundColor(CELL), BorderColor::all(Color::srgb(0.57, 0.59, 0.55)),
                )).with_child((label((cell + 1).to_string(), 40.0), CellLabel(cell)))
                  .observe(move |_: On<Activate>, mut game: ResMut<Game>| { let _ = game.0.play(cell); });
            }
        });
        root.spawn(label("Click a square or press 1–9", 15.0));
    });
}

fn keyboard(keys: Res<ButtonInput<KeyCode>>, mut game: ResMut<Game>) {
    let digits = [KeyCode::Digit1, KeyCode::Digit2, KeyCode::Digit3, KeyCode::Digit4,
        KeyCode::Digit5, KeyCode::Digit6, KeyCode::Digit7, KeyCode::Digit8, KeyCode::Digit9];
    for (cell, key) in digits.into_iter().enumerate() {
        if keys.just_pressed(key) { let _ = game.0.play(cell); }
    }
}

fn status(board: &Board) -> String {
    match board.outcome() {
        Outcome::Playing => format!("{} to move", board.turn().label()),
        Outcome::Won(mark, _) => format!("{} wins", mark.label()),
        Outcome::Draw => "A draw".into(),
    }
}

fn draw(
    game: Res<Game>,
    mut labels: Query<(&mut Text, &mut TextColor, Option<&CellLabel>, Has<StatusLabel>)>,
    mut cells: Query<(&Cell, &mut BackgroundColor)>,
) {
    if !game.is_changed() { return; }
    let message = status(&game.0);
    for (mut text, mut color, cell, is_status) in &mut labels {
        if let Some(cell) = cell {
            let mark = game.0.cells()[cell.0];
            **text = mark.map_or_else(|| (cell.0 + 1).to_string(), |m| m.label().into());
            color.0 = match mark { Some(Mark::X) => X_COLOR, Some(Mark::O) => O_COLOR, None => Color::srgb(0.56, 0.58, 0.54) };
        } else if is_status { **text = message.clone(); }
    }
    for (cell, mut background) in &mut cells {
        let winning = matches!(game.0.outcome(), Outcome::Won(_, line) if line.contains(&cell.0));
        background.0 = if winning { Color::srgb(0.79, 0.87, 0.77) } else { CELL };
    }
    announce(&game.0, &message);
}

// A read-only description of the Rust state for screen readers and browser checks.
fn announce(board: &Board, message: &str) {
    #[cfg(target_arch = "wasm32")]
    if let Some(document) = web_sys::window().and_then(|window| window.document()) {
        if let Some(element) = document.get_element_by_id("game-status") {
            element.set_text_content(Some(message));
            let cells: String = board.cells().iter().map(|m| m.map_or('.', |m| if m == Mark::X { 'X' } else { 'O' })).collect();
            let _ = element.set_attribute("data-cells", &cells);
            let _ = element.set_attribute("data-turn", board.turn().label());
        }
    }
    #[cfg(not(target_arch = "wasm32"))]
    let _ = (board, message);
}

